354	// DeleteNodes deletes the nodes from the group.
355	func (ng *AwsNodeGroup) DeleteNodes(ctx context.Context, nodes []*apiv1.Node) error {
356		size := ng.asg.curSize
357		if int(size) <= ng.MinSize(context.TODO()) {
358			return fmt.Errorf("min size reached, nodes will not be deleted")
359		}
360		refs := make([]*AwsInstanceRef, 0, len(nodes))
361		for _, node := range nodes {
362			belongs, err := ng.Belongs(node)
363			if err != nil {
364				return err
365			}
366			if !belongs {
367				return fmt.Errorf("%s belongs to a different asg than %s", node.Name, ng.Id())
368			}
369			awsref, err := AwsRefFromProviderId(node.Spec.ProviderID)
370			if err != nil {
371				return err
372			}
373			refs = append(refs, awsref)
374		}
375		return ng.awsManager.DeleteInstances(refs)
376	}
