393	// Nodes returns a list of all nodes that belong to this node group.
394	func (ng *AwsNodeGroup) Nodes(ctx context.Context) ([]cloudprovider.Instance, error) {
395		asgNodes, err := ng.awsManager.GetAsgNodes(ng.asg.AwsRef)
396		if err != nil {
397			return nil, err
398		}
399	
400		instances := make([]cloudprovider.Instance, len(asgNodes))
401	
402		for i, asgNode := range asgNodes {
403			var status *cloudprovider.InstanceStatus
404			instanceStatusString, err := ng.awsManager.GetInstanceStatus(asgNode)
405			if err != nil {
406				klog.V(4).Infof("Could not get instance status, continuing anyways: %v", err)
407			} else if instanceStatusString != nil && *instanceStatusString == placeholderUnfulfillableStatus {
408				status = &cloudprovider.InstanceStatus{
409					State: cloudprovider.InstanceCreating,
410					ErrorInfo: &cloudprovider.InstanceErrorInfo{
411						ErrorClass:   cloudprovider.OutOfResourcesErrorClass,
412						ErrorCode:    placeholderUnfulfillableStatus,
413						ErrorMessage: "AWS cannot provision any more instances for this node group",
414					},
415				}
416			}
417			instances[i] = cloudprovider.Instance{
418				Id:     asgNode.ProviderID,
419				Status: status,
420			}
421		}
422		return instances, nil
