444	// BuildAWS builds AWS cloud provider, manager etc.
445	func BuildAWS(opts *coreoptions.AutoscalerOptions, do cloudprovider.NodeGroupDiscoveryOptions, rl *cloudprovider.ResourceLimiter) cloudprovider.CloudProvider {
446		var cfg io.ReadCloser
447		if opts.CloudConfig != "" {
448			var err error
449			cfg, err = os.Open(opts.CloudConfig)
450			if err != nil {
451				klog.Fatalf("Couldn't open cloud provider configuration %s: %#v", opts.CloudConfig, err)
452			}
453			defer cfg.Close()
454		}
455	
456		sdkProvider, err := createAWSSDKProvider(cfg)
457		if err != nil {
458			klog.Fatalf("Failed to create AWS SDK Provider: %v", err)
459		}
460	
461		// Generate EC2 list
462		instanceTypes, lastUpdateTime := GetStaticEC2InstanceTypes()
463		if opts.AWSUseStaticInstanceList {
464			klog.Warningf("Using static EC2 Instance Types, this list could be outdated. Last update time: %s", lastUpdateTime)
465		} else {
466			generatedInstanceTypes, err := GenerateEC2InstanceTypes(sdkProvider.cfg)
467			if err != nil {
468				klog.Errorf("Failed to generate AWS EC2 Instance Types: %v, falling back to static list with last update time: %s", err, lastUpdateTime)
469			}
470			if generatedInstanceTypes == nil {
471				generatedInstanceTypes = map[string]*InstanceType{}
472			}
473			// fallback on the static list if we miss any instance types in the generated output
474			// credits to: https://github.com/lyft/cni-ipvlan-vpc-k8s/pull/80
475			for k, v := range instanceTypes {
476				_, ok := generatedInstanceTypes[k]
477				if ok {
478					continue
479				}
480				klog.Infof("Using static instance type %s", k)
481				generatedInstanceTypes[k] = v
482			}
483			instanceTypes = generatedInstanceTypes
484	
485			keys := make([]string, 0, len(instanceTypes))
486			for key := range instanceTypes {
487				keys = append(keys, key)
488			}
489	
490			klog.Infof("Successfully load %d EC2 Instance Types %s", len(keys), keys)
491		}
492	
493		manager, err := CreateAwsManager(sdkProvider, do, instanceTypes)
494		if err != nil {
495			klog.Fatalf("Failed to create AWS Manager: %v", err)
496		}
497	
498		provider, err := BuildAwsCloudProvider(manager, rl)
499		if err != nil {
500			klog.Fatalf("Failed to create AWS cloud provider: %v", err)
501		}
502		RegisterMetrics()
503	
504		// Configure AWS specific processors
505		if opts.Processors != nil {
506			opts.Processors.TemplateNodeInfoProvider = nodeinfosprovider.NewAsgTagResourceNodeInfoProvider(&opts.AutoscalingOptions.NodeInfoCacheExpireTime, opts.AutoscalingOptions.ForceDaemonSets)
507			opts.Processors.NodeGroupSetProcessor = &nodegroupset.BalancingNodeGroupSetProcessor{
508				Comparator: nodegroupset.CreateAwsNodeInfoComparator(opts.AutoscalingOptions.BalancingExtraIgnoredLabels, opts.AutoscalingOptions.NodeGroupSetRatios),
509			}
510		}
511	
512		return provider
513	}

